import React from "react";
import ReactSpeedometer from "react-d3-speedometer";

function RiskMeter({ score = 0 }) {
  // Ensure score is a valid number
  const parsedScore = typeof score === "number" ? score : parseFloat(score) || 0;

  return (
    <div className="speedometer-wrapper">
      <ReactSpeedometer
        fluidWidth={true}
        minValue={0}
        maxValue={100}
        value={parsedScore}
        // Custom segment boundaries to match exactly:
        // Green (0-30), Yellow (30-60), Red (60-100)
        customSegmentStops={[0, 30, 60, 100]}
        segmentColors={[
          "#10b981", // Low Risk (Safe): Emerald Green
          "#f59e0b", // Moderate Risk: Amber Yellow
          "#ef4444", // High Risk: Rose Red
        ]}
        needleColor="#f8fafc"
        needleTransition="easeElastic"
        needleTransitionDuration={1200}
        currentValueText=" " // Hide internal value text to display custom styled numerical display
        textColor="#94a3b8"
        ringWidth={30}
        maxSegmentLabels={5} // Shows ticks like 0, 30, 60, 100 clearly
      />
      <div className="speedometer-numerical-val animate-fade-in">
        <span className="numerical-score-glow">{parsedScore}%</span>
      </div>
    </div>
  );
}

export default RiskMeter;
